<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\KycStatus;
use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/**
 * One identity-verification case per user. Personal and document fields are
 * encrypted at rest; provider output is reduced to the checks reviewers need.
 */
/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $user_id
 * @property string $code
 * @property KycStatus $status
 * @property string $step
 * @property string|null $legal_first_name
 * @property string|null $legal_last_name
 * @property string|null $date_of_birth
 * @property string|null $nationality
 * @property string|null $document_type
 * @property string|null $document_country
 * @property string|null $document_number
 * @property Carbon|null $document_expires_on
 * @property string|null $document_front_media_id
 * @property string|null $document_back_media_id
 * @property string|null $selfie_media_id
 * @property string|null $handoff_token_hash
 * @property Carbon|null $handoff_expires_at
 * @property string|null $provider
 * @property string|null $provider_reference
 * @property array|null $automated_checks
 * @property array|null $extracted
 * @property string|null $checks_status
 * @property string|null $rejection_reason
 * @property string|null $reviewer_note
 * @property string|null $reviewed_by
 * @property Carbon|null $submitted_at
 * @property Carbon|null $reviewed_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class KycVerification extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'kyc';

    protected $fillable = [
        'user_id', 'code', 'status', 'step', 'legal_first_name', 'legal_last_name', 'date_of_birth', 'nationality',
        'document_type', 'document_country', 'document_number', 'document_expires_on', 'document_front_media_id',
        'document_back_media_id', 'selfie_media_id', 'handoff_token_hash', 'handoff_expires_at', 'provider',
        'provider_reference', 'automated_checks', 'extracted', 'checks_status', 'rejection_reason', 'reviewer_note',
        'reviewed_by', 'submitted_at', 'reviewed_at',
    ];

    protected $hidden = ['legal_first_name', 'legal_last_name', 'date_of_birth', 'document_number', 'handoff_token_hash'];

    protected $attributes = ['status' => 'not_started', 'step' => 'personal_details'];

    protected function casts(): array
    {
        return [
            'status' => KycStatus::class,
            'legal_first_name' => 'encrypted',
            'legal_last_name' => 'encrypted',
            'date_of_birth' => 'encrypted',
            'document_number' => 'encrypted',
            'document_expires_on' => 'date',
            'automated_checks' => 'array',
            'extracted' => 'array',
            'handoff_expires_at' => 'datetime',
            'submitted_at' => 'datetime',
            'reviewed_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }

    /** @return BelongsTo<Media, $this> */
    public function documentFront(): BelongsTo
    {
        return $this->belongsTo(Media::class, 'document_front_media_id');
    }

    /** @return BelongsTo<Media, $this> */
    public function documentBack(): BelongsTo
    {
        return $this->belongsTo(Media::class, 'document_back_media_id');
    }

    /** @return BelongsTo<Media, $this> */
    public function selfie(): BelongsTo
    {
        return $this->belongsTo(Media::class, 'selfie_media_id');
    }

    /** @return BelongsTo<User, $this> */
    public function reviewer(): BelongsTo
    {
        return $this->belongsTo(User::class, 'reviewed_by');
    }
}
